window.TIMING = {"open-title":{"dur":44.7,"beats":[{"start":2.2,"sents":[{"start":2.2,"end":10.73,"cap":"In 1965, G. Evelyn Hutchinson described nature as the ecological theater: the stage on which the evolutionary play is performed."}],"end":10.73},{"start":11.48,"sents":[{"start":11.48,"end":14.902,"cap":"Every question in ecology asks some version of the same thing."},{"start":15.222,"end":19.496,"cap":"Why are these organisms here, in these numbers, alongside these neighbors?"}],"end":19.496},{"start":20.246,"sents":[{"start":20.246,"end":28.568,"cap":"Ecologists answer with theory: a toolkit of models for growth, niches, competition, predation, and movement across landscapes."}],"end":28.568},{"start":29.918,"sents":[{"start":29.918,"end":34.977,"cap":"In this program we build that toolkit, from a single population up to whole metacommunities."},{"start":35.297,"end":37.574,"cap":"Watch the lexicon on the right of the screen."},{"start":37.894,"end":41.2,"cap":"Every numbered term is one an examiner may ask you to define."}],"end":41.2}],"sig":"594:0,0,0.6,1.5"},"pop-card":{"dur":7.729,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.722,"cap":"Chapter one."},{"start":2.042,"end":6.129,"cap":"Population dynamics: the rules by which numbers change through time."}],"end":6.129}],"sig":"81:0"},"pop-exp":{"dur":63.069,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.624,"cap":"Begin with a single population and no limits."},{"start":3.944,"end":16.433,"cap":"If each individual has a constant per-capita birth rate, b, and death rate, d, the population grows as dN/dt = rN, where r = b − d is the intrinsic rate of increase."}],"end":16.433},{"start":17.183,"sents":[{"start":17.183,"end":26.645,"cap":"The result is exponential growth: a J-shaped curve in which the population doubles every ln 2 / r time units, no matter how large it already is."}],"end":26.645},{"start":27.395,"sents":[{"start":27.395,"end":34.003,"cap":"Species that breed in discrete pulses follow the geometric model, N(t+1) = λN(t)."},{"start":34.323,"end":37.88,"cap":"Lambda, the finite rate of increase, equals e^r."},{"start":38.2,"end":46.549,"cap":"When λ > 1 the population grows, when λ < 1 it declines, and when λ = 1 it simply replaces itself."}],"end":46.549},{"start":47.299,"sents":[{"start":47.299,"end":51.843,"cap":"Both models are density-independent: per-capita rates do not change with crowding."},{"start":52.163,"end":61.769,"cap":"No population sustains this for long, but it is the baseline every other model modifies, and it describes invasions and recoveries surprisingly well in their early phases."}],"end":61.769}],"sig":"965:0,0,0,0"},"pop-logistic":{"dur":65.509,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.86,"cap":"No population grows forever."},{"start":3.18,"end":8.91,"cap":"As density rises, resources dwindle and per-capita growth declines: density dependence."},{"start":9.23,"end":15.079,"cap":"Its simplest form is the logistic model, dN/dt = rN(1 − N/K)."}],"end":15.079},{"start":15.829,"sents":[{"start":15.829,"end":19.971,"cap":"K is the carrying capacity, the density at which births balance deaths."},{"start":20.291,"end":29.788,"cap":"Population growth is fastest at K/2, the inflection point of the S-shaped curve, which is why classic fisheries models place maximum sustainable yield there."}],"end":29.788},{"start":30.538,"sents":[{"start":30.538,"end":34.208,"cap":"Density dependence can act on births, deaths, or both."},{"start":34.528,"end":47.667,"cap":"It is compensatory when recruitment levels off at high density, as in the Beverton–Holt model, and overcompensatory when recruitment actually falls at high density, as in the Ricker model, which can produce boom-and-bust dynamics."}],"end":47.667},{"start":48.417,"sents":[{"start":48.417,"end":51.13,"cap":"At very low density the relationship can reverse."},{"start":51.45,"end":58.191,"cap":"Under an Allee effect, per-capita growth increases with density, because mates are hard to find or group defenses fail."},{"start":58.511,"end":64.209,"cap":"A strong Allee effect creates a critical threshold below which the population declines toward extinction."}],"end":64.209}],"sig":"1001:0,0,0,0"},"pop-chaos":{"dur":62.51,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.486,"cap":"Density dependence rarely acts instantly."},{"start":3.806,"end":10.978,"cap":"If growth responds to density at some time τ in the past, a population can overshoot its carrying capacity."}],"end":10.978},{"start":11.728,"sents":[{"start":11.728,"end":19.109,"cap":"In Hutchinson’s lagged logistic, small values of rτ give a smooth approach to K. Intermediate values give damped oscillations."},{"start":19.429,"end":27.709,"cap":"When rτ exceeds π/2, about 1.57, the population settles into a stable limit cycle and oscillates indefinitely."}],"end":27.709},{"start":28.459,"sents":[{"start":28.459,"end":32.208,"cap":"Populations with discrete generations can do stranger things still."},{"start":32.528,"end":44.855,"cap":"In the logistic map, studied by Robert May in 1976, raising the growth rate drives the population from a stable point, through a cascade of period-doubling bifurcations, into deterministic chaos."}],"end":44.855},{"start":47.105,"sents":[{"start":47.105,"end":55.474,"cap":"Chaos means erratic, aperiodic fluctuations generated by a simple deterministic rule, with extreme sensitivity to initial conditions."},{"start":55.794,"end":60.21,"cap":"May’s lesson: complex dynamics in nature need not have complex causes."}],"end":60.21}],"sig":"890:0,0,1.5,1"},"pop-structure":{"dur":85.51,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3,"cap":"Real populations have structure."},{"start":3.32,"end":13.289,"cap":"A life table tracks survivorship, lₓ, the proportion of a cohort alive at age x, and fecundity, mₓ, the offspring produced per individual at that age."}],"end":13.289},{"start":14.039,"sents":[{"start":14.039,"end":16.817,"cap":"Survivorship curves come in three classic types."},{"start":17.137,"end":21.665,"cap":"Type I: most individuals survive to old age, as in large mammals."},{"start":21.985,"end":26.06,"cap":"Type II: a constant risk of death at every age, as in many birds."},{"start":26.38,"end":31.616,"cap":"Type III: massive early mortality, as in oysters, most fish, and trees."}],"end":31.616},{"start":32.366,"sents":[{"start":32.366,"end":39.787,"cap":"Summing lₓmₓ across ages gives R₀, the net reproductive rate: expected lifetime offspring per individual."},{"start":40.107,"end":44.068,"cap":"When R₀ > 1, the population grows each generation."}],"end":44.068},{"start":44.818,"sents":[{"start":44.818,"end":47.249,"cap":"Matrix models generalize the life table."},{"start":47.569,"end":57.237,"cap":"In a Leslie matrix, organized by age, or a Lefkovitch matrix, organized by stage, the dominant eigenvalue is the asymptotic growth rate λ."},{"start":57.557,"end":63.583,"cap":"The right eigenvector is the stable stage distribution, and the left eigenvector gives reproductive values."}],"end":63.583},{"start":64.333,"sents":[{"start":64.333,"end":68.98,"cap":"Sensitivity and elasticity analyses ask which vital rate most affects λ."},{"start":69.3,"end":83.21,"cap":"For loggerhead sea turtles, Crouse and colleagues showed in 1987 that λ responds far more to the survival of large juveniles than to egg survival, shifting conservation from nesting beaches toward turtle excluder devices on shrimp trawls."}],"end":83.21}],"sig":"1252:0,0,0,0,1"},"pop-stoch":{"dur":95.304,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.529,"cap":"Finally, chance."},{"start":2.849,"end":9.218,"cap":"Demographic stochasticity is randomness in the fates of individuals: who lives, who dies, who breeds."},{"start":9.538,"end":11.845,"cap":"It matters most in small populations."},{"start":12.165,"end":20.498,"cap":"Environmental stochasticity is year-to-year variation in vital rates that affects all individuals together, and catastrophes are its extreme form."}],"end":20.498},{"start":21.248,"sents":[{"start":21.248,"end":27.641,"cap":"Under environmental variation, long-run growth follows the geometric mean of λ, not the arithmetic mean."},{"start":27.961,"end":37.09,"cap":"Because the geometric mean is always lower, variability itself depresses growth: a population averaging λ = 1.05 can still decline."}],"end":37.09},{"start":37.84,"sents":[{"start":37.84,"end":47.5,"cap":"Population viability analysis projects these processes forward to estimate extinction risk, often as the probability of falling below a quasi-extinction threshold."},{"start":47.82,"end":57.023,"cap":"A minimum viable population is the smallest size with an acceptable chance of persistence; Shaffer’s classic benchmark was ninety-nine percent over a thousand years."}],"end":57.023},{"start":57.773,"sents":[{"start":57.773,"end":66.239,"cap":"Small populations can spiral downward as inbreeding, lost genetic variation, Allee effects, and stochasticity reinforce one another."},{"start":66.559,"end":70.556,"cap":"Gilpin and Soulé called this the extinction vortex in 1986."}],"end":70.556},{"start":71.306,"sents":[{"start":71.306,"end":72.994,"cap":"Life history ties it together."},{"start":73.314,"end":84.812,"cap":"MacArthur and Wilson’s r- and K-selection contrasted fast, fecund species favored in uncrowded, unpredictable settings with slow, competitive species favored near carrying capacity."},{"start":85.132,"end":93.004,"cap":"Today the fast–slow continuum and Grime’s C-S-R triangle of competitors, stress-tolerators, and ruderals refine that dichotomy."}],"end":93.004}],"sig":"1442:0,0,0,0,1"},"niche-card":{"dur":6.886,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.722,"cap":"Chapter two."},{"start":2.042,"end":5.286,"cap":"Niche theory: what a species needs, and what it does."}],"end":5.286}],"sig":"66:0"},"niche-concepts":{"dur":65.589,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.443,"cap":"The niche is ecology’s most used, and most argued-over, concept."},{"start":5.763,"end":12.885,"cap":"Joseph Grinnell, in 1917, framed it as a species’ habitat requirements: the conditions where it can live."},{"start":13.205,"end":18.836,"cap":"The niche of his California thrasher was the chaparral that met its needs for food, cover, and nesting."}],"end":18.836},{"start":19.586,"sents":[{"start":19.586,"end":28.605,"cap":"Charles Elton, in 1927, emphasized function instead: a species’ place in the biotic environment, its relations to food and enemies."},{"start":28.925,"end":34.226,"cap":"As Eugene Odum later put it, habitat is a species’ address, and the niche is its profession."}],"end":34.226},{"start":34.976,"sents":[{"start":34.976,"end":39.544,"cap":"G. Evelyn Hutchinson, in 1957, made the niche quantitative."},{"start":39.864,"end":45.983,"cap":"Treat each environmental factor, such as temperature, moisture, or food size, as an axis."},{"start":46.303,"end":52.805,"cap":"The set of conditions under which a species can persist forms an n-dimensional hypervolume: the Hutchinsonian niche."}],"end":52.805},{"start":53.555,"sents":[{"start":53.555,"end":54.491,"cap":"Notice the shift."},{"start":54.811,"end":60.861,"cap":"Grinnell and Elton described niches as places or roles in the environment and the community, waiting to be filled."},{"start":61.181,"end":64.289,"cap":"Hutchinson made the niche a property of the species itself."}],"end":64.289}],"sig":"961:0,0,0,0"},"niche-realized":{"dur":61.82,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":16.305,"cap":"Hutchinson distinguished the fundamental niche, the full range of conditions where a species could persist on its physiological tolerances alone, from the realized niche, the narrower range it actually occupies once competitors, predators, and pathogens are present."}],"end":16.305},{"start":17.055,"sents":[{"start":17.055,"end":24.166,"cap":"Joseph Connell’s experiments on the Isle of Cumbrae, in Scotland, published in 1961, made this vivid."},{"start":24.486,"end":26.367,"cap":"Two barnacles share the rocky shore."},{"start":26.687,"end":32.818,"cap":"Chthamalus lives high in the intertidal zone, and Balanus, now called Semibalanus, lives below it."}],"end":32.818},{"start":33.568,"sents":[{"start":33.568,"end":38.098,"cap":"When Connell removed Balanus, Chthamalus survived and thrived far lower on the shore."},{"start":38.418,"end":44.661,"cap":"Its fundamental niche extended deep, but there the faster-growing Balanus smothered, undercut, and crushed it."},{"start":44.981,"end":48.967,"cap":"Meanwhile, desiccation at low tide set the upper limit of Balanus."}],"end":48.967},{"start":49.717,"sents":[{"start":49.717,"end":51.585,"cap":"This yields a widely observed rule."},{"start":51.905,"end":59.72,"cap":"Physical stress tends to set a species’ range limit on the harsh side of a gradient, while biotic interactions set the limit on the benign side."}],"end":59.72}],"sig":"947:0,0,0,0.8"},"niche-partition":{"dur":87.881,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":7.633,"cap":"Hutchinson’s 1959 essay, Homage to Santa Rosalia, asked why there are so many kinds of animals."},{"start":7.953,"end":9.766,"cap":"One answer is niche partitioning."},{"start":10.086,"end":19.812,"cap":"In 1958, Robert MacArthur showed that five species of warbler coexist in the same spruce forests by foraging in different parts of the trees, in different ways."}],"end":19.812},{"start":20.562,"sents":[{"start":20.562,"end":25.343,"cap":"Picture each species as a resource utilization curve along an axis such as prey size."},{"start":25.663,"end":30.966,"cap":"Each curve has a width, w, and neighboring curves are separated by a distance, d."},{"start":31.286,"end":34.895,"cap":"The overlap between curves measures the potential for competition."}],"end":34.895},{"start":35.645,"sents":[{"start":35.645,"end":45.529,"cap":"MacArthur and Levins argued in 1967 for limiting similarity: a maximum overlap compatible with coexistence, reached roughly when d falls below w."},{"start":45.849,"end":54.96,"cap":"Hutchinson had noticed that coexisting congeners often differ in body or bill size by a ratio of about 1.3, though that pattern proved weaker than first thought."}],"end":54.96},{"start":55.71,"sents":[{"start":55.71,"end":61.284,"cap":"Where competitors meet, natural selection can push their traits apart: character displacement."},{"start":61.604,"end":72.793,"cap":"In the Galápagos, the ground finches Geospiza fortis and G. fuliginosa have distinct beak depths where they co-occur, but converge on intermediate beaks on islands where each lives alone."}],"end":72.793},{"start":74.343,"sents":[{"start":74.343,"end":82.491,"cap":"Present-day partitioning may therefore be the ghost of competition past, Connell’s phrase for patterns shaped by competition that no longer operates."},{"start":82.811,"end":86.581,"cap":"A lack of competition today does not mean competition never mattered."}],"end":86.581}],"sig":"1368:0,0,0,0.8,0"},"niche-modern":{"dur":74.704,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":7.169,"cap":"In 2003, Jonathan Chase and Mathew Leibold reunited the Grinnellian and Eltonian traditions."},{"start":7.489,"end":17.668,"cap":"A species’ niche has two halves: its requirements, the conditions under which its per-capita growth rate is at least zero, and its impacts, the effects it has on those conditions."}],"end":17.668},{"start":18.418,"sents":[{"start":18.418,"end":24.415,"cap":"On a graph of two resources, requirements become a zero net growth isocline, or ZNGI."},{"start":24.735,"end":28.295,"cap":"Above the line the population grows; below it, it shrinks."},{"start":28.615,"end":33.523,"cap":"Impacts become consumption vectors, showing how the species depletes each resource."},{"start":33.843,"end":39.196,"cap":"Tilman’s resource competition theory, coming next, is built from exactly these pieces."}],"end":39.196},{"start":39.946,"sents":[{"start":39.946,"end":47.527,"cap":"The Grinnellian niche lives on in species distribution models, which relate occurrences to environmental layers to map suitable habitat."},{"start":47.847,"end":59.994,"cap":"Soberón and Peterson’s BAM diagram clarifies what such models estimate: a species occurs where suitable abiotic conditions, favorable biotic interactions, and access through movement all overlap."}],"end":59.994},{"start":60.744,"sents":[{"start":60.744,"end":63.95,"cap":"Finally, organisms reshape their own environments."},{"start":64.27,"end":67.107,"cap":"Beavers flood valleys; earthworms remake soils."},{"start":67.427,"end":72.604,"cap":"This niche construction can alter natural selection on the constructors and on everyone around them."}],"end":72.604}],"sig":"1127:0,0,0,0.8"},"comp-card":{"dur":8.019,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.757,"cap":"Chapter three."},{"start":2.077,"end":6.419,"cap":"Competition: what happens when organisms need the same limited resources."}],"end":6.419}],"sig":"88:0"},"comp-types":{"dur":98.8,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":8.402,"cap":"Competition is a mutually negative interaction, minus–minus, between organisms that require the same limited resource."},{"start":8.722,"end":13.967,"cap":"Intraspecific competition occurs among members of one species and drives density dependence."},{"start":14.287,"end":17.361,"cap":"Interspecific competition occurs between species."}],"end":17.361},{"start":18.111,"sents":[{"start":18.111,"end":26.614,"cap":"By mechanism, exploitative competition is indirect: individuals deplete a shared resource, such as water, nitrogen, or prey."},{"start":26.934,"end":35.58,"cap":"Interference competition is direct: individuals prevent others from using a resource, through aggression, territoriality, or chemical means."}],"end":35.58},{"start":36.33,"sents":[{"start":36.33,"end":57.646,"cap":"Thomas Schoener, in 1983, listed six mechanisms: consumptive competition for resources; preemptive, occupying space first; overgrowth, as when plants or corals shade one another; chemical, or allelopathy, like the juglone released by black walnut; territorial; and encounter, such as fights at a carcass."}],"end":57.646},{"start":58.396,"sents":[{"start":58.396,"end":70.455,"cap":"A. J. Nicholson contrasted scramble competition, where resources are divided so evenly that every individual gets too little, with contest competition, where winners secure what they need and losers get nothing."},{"start":70.775,"end":79.982,"cap":"Competition is also often asymmetric: in plants, competition for light is size-asymmetric, because taller plants shade shorter ones disproportionately."}],"end":79.982},{"start":80.732,"sents":[{"start":80.732,"end":85.649,"cap":"And beware apparent competition, described by Robert Holt in 1977."},{"start":85.969,"end":91.321,"cap":"Two prey species that never share a resource can still depress each other by sustaining a shared predator."},{"start":91.641,"end":96.7,"cap":"In field data it looks just like competition, but it is mediated by a natural enemy."}],"end":96.7}],"sig":"1459:0,0,0,0,0.8"},"comp-lv":{"dur":91.456,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.572,"cap":"The Lotka–Volterra competition model extends the logistic."},{"start":4.892,"end":11.705,"cap":"Each species’ growth is slowed by its own density and by the density of its competitor, scaled by a competition coefficient."},{"start":12.025,"end":19.486,"cap":"α₁₂ is the per-capita effect of species two on species one, measured relative to the effect of species one on itself."}],"end":19.486},{"start":20.236,"sents":[{"start":20.236,"end":22.22,"cap":"Plot both species in a phase plane."},{"start":22.54,"end":28.749,"cap":"Each species has a zero-growth isocline, a straight line along which its population neither grows nor shrinks."},{"start":29.069,"end":34.998,"cap":"How the two lines sit relative to each other determines the outcome, and there are exactly four possibilities."}],"end":34.998},{"start":35.748,"sents":[{"start":35.748,"end":41.399,"cap":"If species one’s isocline lies entirely outside species two’s, species one always wins."},{"start":41.719,"end":43.909,"cap":"Reverse them, and species two wins."},{"start":44.229,"end":46.327,"cap":"Either way, the loser is excluded."},{"start":46.647,"end":55.952,"cap":"Georgii Gause saw this in his Paramecium cultures in the 1930s, which gave us the competitive exclusion principle: complete competitors cannot coexist."}],"end":55.952},{"start":57.202,"sents":[{"start":57.202,"end":65.86,"cap":"If the isoclines cross, and each species limits itself more than it limits its competitor, the crossing is a stable equilibrium: coexistence."},{"start":66.18,"end":71.158,"cap":"If instead each limits its competitor more than itself, the crossing is an unstable saddle."},{"start":71.478,"end":77.308,"cap":"One species still wins, but which one depends on who starts ahead, a classic priority effect."}],"end":77.308},{"start":78.558,"sents":[{"start":78.558,"end":85.792,"cap":"The rule to remember: stable coexistence requires intraspecific competition to be stronger than interspecific competition."},{"start":86.112,"end":89.156,"cap":"Species must limit themselves more than they limit each other."}],"end":89.156}],"sig":"1395:0,0,0.5,0.5,1"},"comp-rstar":{"dur":71.496,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.632,"cap":"Lotka–Volterra describes the outcome of competition, but not its mechanism."},{"start":5.952,"end":10.011,"cap":"David Tilman’s resource competition theory makes the mechanism explicit."},{"start":10.331,"end":17.821,"cap":"For a single limiting resource, each species has an R*, the resource level at which its growth exactly balances its losses."}],"end":17.821},{"start":18.571,"sents":[{"start":18.571,"end":22.26,"cap":"A consumer draws the resource down until it reaches its own R*."},{"start":22.58,"end":31.406,"cap":"So when species compete for one resource, the species with the lowest R* wins: it depresses the resource below the level its competitor needs to persist."},{"start":31.726,"end":37.123,"cap":"This R* rule has held up in experiments with algae, bacteria, and grassland plants."}],"end":37.123},{"start":38.373,"sents":[{"start":38.373,"end":45.852,"cap":"With two essential resources, each species’ zero net growth isocline is L-shaped, and two species’ isoclines can cross."},{"start":46.172,"end":54.367,"cap":"They coexist stably when each species is more limited by a different resource, and each consumes relatively more of the resource that limits it most."}],"end":54.367},{"start":55.117,"sents":[{"start":55.117,"end":60.39,"cap":"Which outcome occurs depends on the supply point, the rates at which the two resources are supplied."},{"start":60.71,"end":69.196,"cap":"That is Tilman’s resource-ratio hypothesis: shifting the ratio of nutrients, by fertilization for instance, can reorder which species win."}],"end":69.196}],"sig":"1100:0,0.5,0,1"},"comp-chesson":{"dur":99.269,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":6.578,"cap":"Peter Chesson’s modern coexistence theory, published in 2000, reorganized all of this."},{"start":6.898,"end":15.289,"cap":"Its test for coexistence is mutual invasibility: each species must be able to increase when rare, invading a community dominated by the other."}],"end":15.289},{"start":16.039,"sents":[{"start":16.039,"end":17.878,"cap":"Mechanisms come in two kinds."},{"start":18.198,"end":27.453,"cap":"Stabilizing mechanisms, or niche differences, cause species to limit themselves more than each other, so any species gains an advantage when it becomes rare."},{"start":27.773,"end":34.712,"cap":"Equalizing mechanisms shrink average fitness differences, the inherent competitive advantage of one species over another."}],"end":34.712},{"start":35.462,"sents":[{"start":35.462,"end":39.516,"cap":"Species coexist when niche differences overcome fitness differences."},{"start":39.836,"end":44.138,"cap":"On this plane, the zone of coexistence widens as niche differences grow."},{"start":44.458,"end":50.805,"cap":"Equalizing mechanisms alone can never produce stable coexistence, but they reduce the niche difference required."}],"end":50.805},{"start":52.055,"sents":[{"start":52.055,"end":60.44,"cap":"Stabilizing mechanisms include resource partitioning and Janzen–Connell effects, where specialist natural enemies kill seedlings near their parents."},{"start":60.76,"end":62.716,"cap":"Others depend on fluctuations."},{"start":63.036,"end":72.302,"cap":"The storage effect operates when species respond differently to a variable environment and can store gains, in seed banks or long-lived adults, through bad years."},{"start":72.622,"end":78.201,"cap":"Relative nonlinearity operates when species respond nonlinearly to fluctuating resources."}],"end":78.201},{"start":78.951,"sents":[{"start":78.951,"end":89.992,"cap":"Together these ideas resolve Hutchinson’s 1961 paradox of the plankton: how dozens of phytoplankton species coexist on a handful of resources in an apparently well-mixed lake."},{"start":90.312,"end":96.969,"cap":"Variation in time, natural enemies, and hidden spatial structure keep the system from ever reaching exclusion."}],"end":96.969}],"sig":"1514:0,0,0.5,0,1"},"pred-card":{"dur":6.496,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.711,"cap":"Chapter four."},{"start":2.031,"end":4.896,"cap":"Predation: the dynamics of eating and being eaten."}],"end":4.896}],"sig":"64:0"},"pred-lv":{"dur":72.981,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":8.598,"cap":"Predation is a plus–minus interaction, and the term spans true predators, herbivores, parasitoids, and parasites."},{"start":8.918,"end":20.815,"cap":"Its simplest model, from Lotka and Volterra in the 1920s, gives prey exponential growth in the absence of predators, and lets predators convert captured prey into new predators while dying at a constant rate."}],"end":20.815},{"start":21.565,"sents":[{"start":21.565,"end":23.911,"cap":"The model’s signature is coupled oscillation."},{"start":24.231,"end":32.542,"cap":"Prey increase, then predators increase; prey crash, and predators follow, with predator peaks lagging prey peaks by about a quarter cycle."}],"end":32.542},{"start":33.292,"sents":[{"start":33.292,"end":37.921,"cap":"In the phase plane, the two populations circle their equilibrium in closed loops."},{"start":38.241,"end":45.692,"cap":"These neutral cycles have an amplitude set entirely by the starting conditions, and any disturbance shifts the system onto a new cycle."},{"start":46.012,"end":50.1,"cap":"The model is structurally unstable, better for intuition than for prediction."}],"end":50.1},{"start":50.85,"sents":[{"start":50.85,"end":52.444,"cap":"Yet real cycles exist."},{"start":52.764,"end":59.535,"cap":"Snowshoe hares and Canada lynx, recorded in Hudson’s Bay Company fur returns, cycle roughly every ten years."},{"start":59.855,"end":70.881,"cap":"Experiments by Charles Krebs and colleagues in the Yukon showed that the hare cycle arises from food and predation acting together, with predation risk also causing stress that suppresses hare reproduction."}],"end":70.881}],"sig":"1142:0,0,0,0.8"},"pred-fr":{"dur":77.984,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":6.751,"cap":"In 1959, C. S. Holling asked how a predator’s feeding rate changes with prey density."},{"start":7.071,"end":10.912,"cap":"The answer is its functional response, and it comes in three types."}],"end":10.912},{"start":11.662,"sents":[{"start":11.662,"end":17.371,"cap":"A Type I response rises linearly until the predator is satiated, typical of filter feeders."},{"start":17.691,"end":22.343,"cap":"A Type II response decelerates, because each capture costs handling time."},{"start":22.663,"end":29.428,"cap":"Holling’s disc equation gives intake as aN / (1 + ahN), where a is the attack rate and h is the handling time."},{"start":29.748,"end":31.847,"cap":"Intake saturates at 1/h."}],"end":31.847},{"start":32.597,"sents":[{"start":32.597,"end":43.704,"cap":"A Type III response is sigmoid: predators take few prey at low density, then accelerate, through learning a search image, switching between prey types, or because scarce prey find refuges."}],"end":43.704},{"start":44.454,"sents":[{"start":44.454,"end":46.115,"cap":"The type matters for stability."},{"start":46.435,"end":53.809,"cap":"With Type II, per-capita risk to prey falls as prey become more numerous, an inverse density dependence that is destabilizing."},{"start":54.129,"end":61.051,"cap":"With Type III, risk rises with prey density at low densities, which can regulate prey and stabilize the interaction."}],"end":61.051},{"start":61.801,"sents":[{"start":61.801,"end":68.048,"cap":"The numerical response is the change in predator numbers, through reproduction or immigration, as prey increase."},{"start":68.368,"end":75.884,"cap":"Multiply the functional and numerical responses to get the total response: the overall predation pressure on the prey population."}],"end":75.884}],"sig":"1187:0,0,0,0,0.8"},"pred-forage":{"dur":52.558,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.097,"cap":"From the predator’s side, these choices are decisions."},{"start":4.417,"end":11.029,"cap":"Optimal foraging theory assumes that natural selection favors foragers that maximize their net rate of energy intake."}],"end":11.029},{"start":11.779,"sents":[{"start":11.779,"end":18.127,"cap":"In the classic diet model, prey types are ranked by profitability: energy gained per unit of handling time."},{"start":18.447,"end":24.527,"cap":"A forager should always take the most profitable prey, and add lower-ranked prey only when better prey are scarce."},{"start":24.847,"end":30.132,"cap":"Whether to eat a poor item depends on the abundance of good items, not on the abundance of poor ones."}],"end":30.132},{"start":30.882,"sents":[{"start":30.882,"end":35.388,"cap":"For patchy food, Eric Charnov’s marginal value theorem predicts when to leave."},{"start":35.708,"end":45.549,"cap":"Gains within a patch diminish as it is depleted, so a forager should leave when its instantaneous intake rate falls to the average rate for the whole habitat, including travel time."},{"start":45.869,"end":50.258,"cap":"The longer the travel between patches, the longer a forager should stay in each."}],"end":50.258}],"sig":"840:0,0,1"},"pred-rm":{"dur":71.177,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":8.597,"cap":"Add two realistic ingredients, prey self-limitation and a Type II functional response, and you have the Rosenzweig–MacArthur model."},{"start":8.917,"end":10.868,"cap":"The prey isocline becomes a hump."},{"start":11.188,"end":16.505,"cap":"The predator isocline is a vertical line at the prey density where predators just replace themselves."}],"end":16.505},{"start":17.255,"sents":[{"start":17.255,"end":23.487,"cap":"If the predator isocline crosses to the right of the hump, trajectories spiral inward to a stable equilibrium."},{"start":23.807,"end":28.169,"cap":"If it crosses to the left, they spiral outward onto a stable limit cycle."}],"end":28.169},{"start":28.919,"sents":[{"start":28.919,"end":32.235,"cap":"Now enrich the system by raising the prey’s carrying capacity."},{"start":32.555,"end":41.298,"cap":"The hump shifts right, past the predator isocline, and stable coexistence gives way to ever-larger cycles that can drive both species toward extinction."},{"start":41.618,"end":45.941,"cap":"Michael Rosenzweig called this the paradox of enrichment in 1971."}],"end":45.941},{"start":47.491,"sents":[{"start":47.491,"end":54.035,"cap":"Host–parasitoid systems have their own classic, the Nicholson–Bailey model, whose oscillations grow without bound."},{"start":54.355,"end":68.877,"cap":"Persistence returns with aggregated attacks, prey refuges, or spatial structure, echoing Carl Huffaker’s 1958 experiments, in which predatory and herbivorous mites persisted only in a complex, patchy universe of oranges."}],"end":68.877}],"sig":"1071:0,0,0.8,1"},"pred-cascade":{"dur":94.144,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.536,"cap":"Predators can structure entire communities."},{"start":3.856,"end":9.716,"cap":"In 1966, Robert Paine removed the sea star Pisaster from rocky shores in Washington."},{"start":10.036,"end":15.24,"cap":"Without it, mussels monopolized the space and the community dropped from fifteen species to eight."},{"start":15.56,"end":21.397,"cap":"Paine called such species keystones: their impact is disproportionately large relative to their abundance."}],"end":21.397},{"start":22.147,"sents":[{"start":22.147,"end":24.43,"cap":"Effects can cascade down food chains."},{"start":24.75,"end":33.385,"cap":"Hairston, Smith, and Slobodkin’s 1960 green world hypothesis argued that predators hold herbivores in check, keeping the world green."},{"start":33.705,"end":37.844,"cap":"In the Aleutian Islands, sea otters eat sea urchins, which graze kelp."},{"start":38.164,"end":43.878,"cap":"When killer whales began eating otters in the 1990s, urchins boomed and kelp forests collapsed."}],"end":43.878},{"start":44.628,"sents":[{"start":44.628,"end":54.205,"cap":"This alternating pattern of effects down a food chain is a trophic cascade, a form of top-down control, as opposed to bottom-up control by resources and productivity."},{"start":54.525,"end":66.078,"cap":"When top predators disappear, smaller predators can surge: mesopredator release, as when the loss of coyotes from fragmented scrub let foxes and house cats increase, and scrub birds declined."}],"end":66.078},{"start":66.828,"sents":[{"start":66.828,"end":68.881,"cap":"Predators also matter without killing."},{"start":69.201,"end":74.877,"cap":"Prey alter foraging, vigilance, habitat use, and physiology in response to risk."},{"start":75.197,"end":78.423,"cap":"These non-consumptive effects make up the ecology of fear."},{"start":78.743,"end":87.946,"cap":"In a 2011 experiment, Liana Zanette and colleagues found that broadcasting predator calls alone cut song sparrow offspring production by about forty percent."},{"start":88.266,"end":91.844,"cap":"Spatial variation in perceived risk forms a landscape of fear."}],"end":91.844}],"sig":"1435:0,0,0,1"},"isl-card":{"dur":8.294,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.769,"cap":"Chapter five."},{"start":2.089,"end":6.694,"cap":"Island biogeography: species richness as a balance of arrivals and losses."}],"end":6.694}],"sig":"88:0"},"isl-sar":{"dur":59.77,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":5.937,"cap":"Islands are natural experiments: replicated, bounded, and easy to count."},{"start":6.257,"end":11.484,"cap":"One of ecology’s oldest generalizations comes from them, the species–area relationship."},{"start":11.804,"end":13.805,"cap":"Larger areas hold more species."}],"end":13.805},{"start":14.555,"sents":[{"start":14.555,"end":18.639,"cap":"It is usually written as a power law, S = cA^z."},{"start":18.959,"end":25.304,"cap":"On log–log axes this becomes a straight line, log S = log c + z log A, with slope z."}],"end":25.304},{"start":26.054,"sents":[{"start":26.054,"end":31.384,"cap":"For true islands, z usually falls between about 0.2 and 0.35."},{"start":31.704,"end":43.374,"cap":"For nested samples of a contiguous mainland it is lower, roughly 0.12 to 0.17, because small mainland samples include transient species spilling over from the surrounding habitat."}],"end":43.374},{"start":44.124,"sents":[{"start":44.124,"end":51.847,"cap":"With z near 0.3, a tenfold loss of area roughly halves the number of species, a rule of thumb attributed to Philip Darlington."},{"start":52.167,"end":57.67,"cap":"The same arithmetic, run in reverse, underlies many estimates of extinction from habitat loss."}],"end":57.67}],"sig":"887:0,0,0,0.8"},"isl-equil":{"dur":71.851,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":9.236,"cap":"In 1963 and 1967, Robert MacArthur and E. O. Wilson proposed the equilibrium theory of island biogeography."},{"start":9.556,"end":17.613,"cap":"The number of species on an island reflects a dynamic balance between two rates: the immigration of new species and the extinction of resident ones."}],"end":17.613},{"start":18.363,"sents":[{"start":18.363,"end":24.817,"cap":"The immigration rate falls as an island fills, reaching zero when all P species of the mainland source pool are present."},{"start":25.137,"end":31.498,"cap":"The extinction rate rises with richness, because more species means smaller populations and more species to lose."},{"start":31.818,"end":37.987,"cap":"Both curves bend: the best dispersers arrive first, and competition intensifies as species pack in."}],"end":37.987},{"start":38.737,"sents":[{"start":38.737,"end":42.907,"cap":"Where the curves cross lies the equilibrium species richness, Ŝ."},{"start":43.227,"end":50.007,"cap":"The rate at that crossing is the turnover rate: even when richness holds steady, the identity of the species keeps changing."}],"end":50.007},{"start":51.257,"sents":[{"start":51.257,"end":57.244,"cap":"Distance controls immigration: near islands receive more colonists than far ones, the distance effect."},{"start":57.564,"end":64.108,"cap":"Area controls extinction: large islands support larger populations that persist longer, the area effect."},{"start":64.428,"end":69.551,"cap":"So large, near islands hold the most species, and small, far islands the fewest."}],"end":69.551}],"sig":"1074:0,0,0.5,1"},"isl-tests":{"dur":66.139,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.714,"cap":"The theory was tested directly."},{"start":3.034,"end":10.17,"cap":"Daniel Simberloff and E. O. Wilson tented small mangrove islands in the Florida Keys and fumigated them to remove every arthropod."},{"start":10.49,"end":18.759,"cap":"Within about a year, species numbers returned close to their original levels, with the nearest island richest, but the species were often different ones."},{"start":19.079,"end":22.037,"cap":"That is equilibrium with turnover, as predicted."}],"end":22.037},{"start":22.787,"sents":[{"start":22.787,"end":24.014,"cap":"Refinements followed."},{"start":24.334,"end":34.707,"cap":"James Brown and Astrid Kodric-Brown described the rescue effect in 1977: on near islands, immigrants bolster dwindling populations, lowering extinction rates."},{"start":35.027,"end":40.879,"cap":"The target effect works the other way: larger islands intercept more dispersers, raising immigration."},{"start":41.199,"end":45.243,"cap":"Both blur the neat assignment of distance to immigration and area to extinction."}],"end":45.243},{"start":45.993,"sents":[{"start":45.993,"end":48.322,"cap":"Real islands also add time and evolution."},{"start":48.642,"end":54.979,"cap":"Krakatau, sterilized by its 1883 eruption, has been reassembling ever since."},{"start":55.299,"end":63.839,"cap":"And on the most remote archipelagos, like Hawaiʻi, speciation within the islands, not immigration, becomes the main source of new species."}],"end":63.839}],"sig":"987:0,0,1"},"isl-frag":{"dur":65.827,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":8.02,"cap":"The theory’s greatest influence was on conservation, because fragments of habitat behave like islands in a sea of altered land."},{"start":8.34,"end":16.034,"cap":"A newly isolated fragment holds more species than its new, smaller equilibrium, so its richness decays toward that lower level."},{"start":16.354,"end":19.684,"cap":"This decay is called relaxation, or faunal collapse."}],"end":19.684},{"start":20.434,"sents":[{"start":20.434,"end":28.237,"cap":"The species destined to vanish but not yet gone constitute an extinction debt, a debt that will be paid unless habitat is restored or reconnected."},{"start":28.557,"end":38.195,"cap":"William Newmark found in 1987 that western North American national parks had lost mammal species since their establishment, with the smallest parks losing the most."}],"end":38.195},{"start":38.945,"sents":[{"start":38.945,"end":46.801,"cap":"Island theory also sparked the SLOSS debate: for the same total area, is it better to protect a single large reserve or several small ones?"},{"start":47.121,"end":55.883,"cap":"A single large reserve supports area-sensitive species and larger populations; several small reserves can capture more habitat variety and spread risk."},{"start":56.203,"end":63.527,"cap":"The answer depends on nestedness, dispersal, and the threats involved, and the question led directly to metapopulation thinking."}],"end":63.527}],"sig":"1041:0,0,1"},"meta-card":{"dur":7.931,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.85,"cap":"Chapter six."},{"start":2.17,"end":6.331,"cap":"Metapopulations: persistence across a network of habitat patches."}],"end":6.331}],"sig":"78:0"},"meta-levins":{"dur":64.17,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":11.534,"cap":"A metapopulation is a population of populations: a set of local populations in discrete habitat patches, connected by dispersal, each with its own chance of going extinct."},{"start":11.854,"end":18.165,"cap":"Richard Levins coined the term in 1969, while thinking about the control of agricultural pests."}],"end":18.165},{"start":18.915,"sents":[{"start":18.915,"end":23.285,"cap":"Levins tracked not individuals but the fraction of patches occupied, p."},{"start":23.605,"end":31.032,"cap":"Empty patches are colonized at rate c·p·(1 − p), and occupied patches go extinct at rate e·p."},{"start":31.352,"end":35.755,"cap":"So dp/dt = cp(1 − p) − ep."}],"end":35.755},{"start":36.505,"sents":[{"start":36.505,"end":44.2,"cap":"This has the same form as the logistic equation, and occupancy settles at an equilibrium, p* = 1 − e/c."}],"end":44.2},{"start":45.75,"sents":[{"start":45.75,"end":57.732,"cap":"The deep insight: a metapopulation can persist indefinitely even though every local population eventually blinks out, provided colonization outpaces extinction, that is, provided c > e."},{"start":58.052,"end":61.87,"cap":"Persistence is a property of the network, not of any single patch."}],"end":61.87}],"sig":"900:0,0,0.8,1"},"meta-threshold":{"dur":54.842,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.44,"cap":"Now destroy a fraction D of the patches."},{"start":3.76,"end":8.61,"cap":"Equilibrium occupancy becomes p* = 1 − D − e/c."},{"start":8.93,"end":11.966,"cap":"Occupancy falls one-for-one with habitat destroyed."}],"end":11.966},{"start":13.216,"sents":[{"start":13.216,"end":19.532,"cap":"The metapopulation goes extinct when D reaches 1 − e/c, while suitable habitat still remains."},{"start":19.852,"end":26.886,"cap":"This is the extinction threshold: a species can disappear from a landscape that still contains empty, suitable patches."}],"end":26.886},{"start":28.636,"sents":[{"start":28.636,"end":29.786,"cap":"Two lessons follow."},{"start":30.106,"end":37.022,"cap":"Empty patches are not evidence that habitat is unimportant; they may be the very patches the network needs for recolonization."},{"start":37.342,"end":45.094,"cap":"And because decline toward a new equilibrium takes time, species that persist after habitat loss may already be committed to extinction."},{"start":45.414,"end":52.542,"cap":"Tilman and colleagues argued in 1994 that the best competitors, often the poorest colonizers, are the first to go."}],"end":52.542}],"sig":"788:0.5,1,1"},"meta-types":{"dur":66.169,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.719,"cap":"Not every metapopulation looks like Levins’s."},{"start":4.039,"end":11.907,"cap":"In a mainland–island system, one large, effectively permanent population supplies colonists to small, extinction-prone ones."},{"start":12.227,"end":17.913,"cap":"In a patchy population, dispersal is so frequent that the patches behave as a single population."},{"start":18.233,"end":26.601,"cap":"In a nonequilibrium metapopulation, extinctions outpace recolonization, often after fragmentation, and the system is in decline."}],"end":26.601},{"start":27.351,"sents":[{"start":27.351,"end":31.515,"cap":"Ronald Pulliam’s 1988 source–sink model adds habitat quality."},{"start":31.835,"end":38.298,"cap":"In source habitats, births exceed deaths, λ > 1, and surplus individuals emigrate."},{"start":38.618,"end":44.165,"cap":"In sink habitats, λ < 1, and populations persist only through immigration."}],"end":44.165},{"start":44.915,"sents":[{"start":44.915,"end":51.181,"cap":"A large share of a species can live in sinks, so local abundance can be a misleading guide to habitat quality."},{"start":51.501,"end":62.869,"cap":"Worse is an ecological trap: a sink that animals actively prefer, because cues that once signaled good habitat no longer do, as when grassland birds nest in hayfields mowed before their chicks fledge."}],"end":62.869}],"sig":"968:0,0,2"},"meta-hanski":{"dur":49.777,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.895,"cap":"Ilkka Hanski made the theory spatially realistic."},{"start":4.215,"end":16.262,"cap":"His incidence function model predicts each patch’s probability of occupancy from its area, which sets extinction risk, and its connectivity, a sum of contributions from occupied patches weighted by their distance."}],"end":16.262},{"start":17.012,"sents":[{"start":17.012,"end":30.092,"cap":"His test case became the flagship of the field: the Glanville fritillary butterfly, living as a metapopulation across some four thousand dry meadows in Finland’s Åland Islands, where local populations wink out and reappear every year."}],"end":30.092},{"start":30.842,"sents":[{"start":30.842,"end":32.828,"cap":"Two more forces shape persistence."},{"start":33.148,"end":40.34,"cap":"Dispersal provides rescue, but it can also synchronize local dynamics, and so can shared weather, the Moran effect."},{"start":40.66,"end":47.477,"cap":"When patches fluctuate in synchrony they crash together, and the spreading of risk that lets a metapopulation persist is lost."}],"end":47.477}],"sig":"775:0,0,1"},"mc-card":{"dur":7.28,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.804,"cap":"Chapter seven."},{"start":2.124,"end":5.68,"cap":"Metacommunities: linking local communities across a region."}],"end":5.68}],"sig":"74:0"},"mc-scale":{"dur":70.623,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":11.662,"cap":"A metacommunity, as defined by Mathew Leibold and colleagues in 2004, is a set of local communities linked by the dispersal of multiple, potentially interacting species."},{"start":11.982,"end":15.113,"cap":"It is the community-level counterpart of the metapopulation."}],"end":15.113},{"start":15.863,"sents":[{"start":15.863,"end":18.403,"cap":"Its diversity is partitioned across scales."},{"start":18.723,"end":27.833,"cap":"Alpha diversity is local richness; gamma diversity is the regional total; and beta diversity, the variation in composition among sites, links them."},{"start":28.153,"end":32.226,"cap":"In Whittaker’s multiplicative form, γ = α × β."}],"end":32.226},{"start":33.476,"sents":[{"start":33.476,"end":44.927,"cap":"Beta diversity itself has two components: turnover, as species replace one another along gradients, and nestedness, as species-poor sites hold subsets of the species found at richer sites."}],"end":44.927},{"start":46.177,"sents":[{"start":46.177,"end":51.32,"cap":"Community assembly is often pictured as a series of filters acting on a regional species pool."},{"start":51.64,"end":60.679,"cap":"Dispersal determines who arrives, environmental filtering determines who can tolerate local conditions, and biotic interactions determine who remains."},{"start":60.999,"end":68.323,"cap":"Kraft and colleagues cautioned in 2015 that competition can produce patterns easily mistaken for environmental filtering."}],"end":68.323}],"sig":"1047:0,0.5,0.5,1"},"mc-paradigms":{"dur":66.527,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":3.717,"cap":"Leibold and colleagues described four paradigms."},{"start":4.037,"end":17.931,"cap":"In patch dynamics, patches are identical, and species coexist regionally through a competition–colonization trade-off: superior competitors are poor dispersers, so fugitive species persist by reaching empty patches first."}],"end":17.931},{"start":18.681,"sents":[{"start":18.681,"end":25.086,"cap":"In species sorting, patches differ in environmental conditions, and each species does best in different ones."},{"start":25.406,"end":31.647,"cap":"Dispersal is sufficient for species to reach suitable patches, so local composition tracks the environment."},{"start":31.967,"end":34.659,"cap":"This is classic niche theory, set in space."}],"end":34.659},{"start":35.409,"sents":[{"start":35.409,"end":39.585,"cap":"In mass effects, dispersal is so high that it overrides local fitness."},{"start":39.905,"end":48.667,"cap":"Immigrants spill from patches where a species thrives into patches where it cannot persist alone, a community-wide source–sink dynamic that inflates local diversity."},{"start":48.987,"end":53.059,"cap":"At extreme dispersal, the region homogenizes and diversity falls."}],"end":53.059},{"start":53.809,"sents":[{"start":53.809,"end":61.861,"cap":"And in the neutral paradigm, species are demographically equivalent, and composition drifts through chance births, deaths, and dispersal."},{"start":62.181,"end":64.227,"cap":"We will return to it in the next chapter."}],"end":64.227}],"sig":"1016:0,0,0,1"},"mc-dispersal":{"dur":57.249,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.719,"cap":"Across these paradigms, dispersal rate is a master variable."},{"start":5.039,"end":18.195,"cap":"Theory by Nicolas Mouquet and Michel Loreau predicts that local diversity peaks at intermediate dispersal, while beta diversity declines steadily as dispersal homogenizes the region, and regional diversity eventually falls too."}],"end":18.195},{"start":19.445,"sents":[{"start":19.445,"end":33.434,"cap":"To diagnose which processes structure a real metacommunity, ecologists often use variation partitioning: how much variation in species composition is explained by environment alone, by spatial structure alone, and by both together."},{"start":33.754,"end":41.332,"cap":"A large environmental fraction suggests species sorting; a large pure spatial fraction suggests dispersal limitation or drift."}],"end":41.332},{"start":42.082,"sents":[{"start":42.082,"end":44.811,"cap":"Treat these fractions as clues, not verdicts."},{"start":45.131,"end":54.949,"cap":"Unmeasured environmental variables that are spatially structured can masquerade as dispersal effects, and very different processes can leave similar statistical fingerprints."}],"end":54.949}],"sig":"868:0.5,0,1"},"neu-card":{"dur":7.06,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.699,"cap":"Chapter eight."},{"start":2.019,"end":5.46,"cap":"Neutral theory: what chance and dispersal alone can explain."}],"end":5.46}],"sig":"75:0"},"neu-premise":{"dur":71.662,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.056,"cap":"Niche theory explains coexistence through differences."},{"start":4.376,"end":16.191,"cap":"In 2001, Stephen Hubbell’s Unified Neutral Theory of Biodiversity and Biogeography asked a provocative question: how much of nature’s pattern could we explain if species had no differences at all?"}],"end":16.191},{"start":16.941,"sents":[{"start":16.941,"end":26.919,"cap":"Neutral theory assumes ecological equivalence: every individual of every species has identical per-capita chances of birth, death, dispersal, and speciation."},{"start":27.239,"end":30.765,"cap":"It is a theory built on individuals, not on species traits."}],"end":30.765},{"start":31.515,"sents":[{"start":31.515,"end":37.366,"cap":"Communities are zero-sum: a fixed number of individuals, J, saturates the landscape."},{"start":37.686,"end":42.356,"cap":"Whenever one dies, it is replaced by the offspring of another, chosen at random."},{"start":42.676,"end":52.964,"cap":"Species abundances therefore wander by chance, a process called ecological drift, directly analogous to genetic drift in Motoo Kimura’s neutral theory of molecular evolution."}],"end":52.964},{"start":54.514,"sents":[{"start":54.514,"end":60.583,"cap":"In an isolated community, drift alone eventually leads to monodominance: one species takes over."},{"start":60.903,"end":68.862,"cap":"Diversity persists only if it is replenished, by immigration from outside, and, over the longest timescales, by speciation."}],"end":68.862}],"sig":"1031:0,0,0.8,1.5"},"neu-theta":{"dur":77.614,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":2.849,"cap":"Hubbell’s model has two scales."},{"start":3.169,"end":8.322,"cap":"In the metacommunity, new species arise by point speciation, at a rate ν per birth."},{"start":8.642,"end":19.062,"cap":"Diversity there is governed by a single number, the fundamental biodiversity number θ = 2J_Mν, twice the metacommunity size times the speciation rate."},{"start":19.382,"end":25.671,"cap":"At equilibrium, metacommunity abundances follow Fisher’s log-series, and θ equals Fisher’s α."}],"end":25.671},{"start":26.421,"sents":[{"start":26.421,"end":28.922,"cap":"Local communities draw from the metacommunity."},{"start":29.242,"end":37.371,"cap":"With probability m, a dead individual is replaced by an immigrant from the metacommunity; otherwise, by the offspring of a local individual."},{"start":37.691,"end":44.11,"cap":"The immigration probability m sets how strongly dispersal limitation separates local from regional composition."}],"end":44.11},{"start":44.86,"sents":[{"start":44.86,"end":51.176,"cap":"The theory’s central prediction is the species abundance distribution: how many species are common and how many rare."},{"start":51.496,"end":62.156,"cap":"Frank Preston plotted abundances in doubling classes he called octaves, and found a humped, roughly lognormal shape, with the rarest species hidden behind a veil line of incomplete sampling."}],"end":62.156},{"start":62.906,"sents":[{"start":62.906,"end":67.012,"cap":"Hubbell’s zero-sum multinomial reproduces such humped distributions."},{"start":67.332,"end":75.314,"cap":"Dispersal limitation leaves local communities with fewer rare species than the log-series predicts, because rare regional species seldom arrive."}],"end":75.314}],"sig":"1210:0,0,0,1"},"neu-tests":{"dur":63.389,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":8.351,"cap":"Neutral models fit the species abundance distribution of the fifty-hectare forest plot on Barro Colorado Island remarkably well."},{"start":8.671,"end":15.937,"cap":"They also predict distance decay of similarity, as dispersal limitation makes nearby communities more alike than distant ones."}],"end":15.937},{"start":16.687,"sents":[{"start":16.687,"end":19.385,"cap":"But fitting a pattern is weak evidence for a process."},{"start":19.705,"end":31.679,"cap":"Niche-based models can produce the same abundance distributions, and experiments routinely find stabilizing niche differences and species-specific negative density dependence, even among tropical trees."},{"start":31.999,"end":34.742,"cap":"Strict neutrality is almost certainly false."}],"end":34.742},{"start":35.492,"sents":[{"start":35.492,"end":43.72,"cap":"Its lasting value is as a null model: neutral theory shows what chance and dispersal alone can produce, so that departures from it become informative."},{"start":44.04,"end":45.732,"cap":"It also seeded a synthesis."},{"start":46.052,"end":52.341,"cap":"In Chesson’s terms, neutrality is the special case of zero niche differences and zero fitness differences."},{"start":52.661,"end":60.889,"cap":"And Scheffer and van Nes showed how emergent neutrality can arise, with clumps of similar species coexisting almost neutrally within distinct niches."}],"end":60.889}],"sig":"993:0,0,1.2"},"syn-card":{"dur":6.536,"beats":[{"start":0.9,"sents":[{"start":0.9,"end":1.769,"cap":"Chapter nine."},{"start":2.089,"end":4.936,"cap":"Synthesis: one framework for the whole toolkit."}],"end":4.936}],"sig":"61:0"},"syn-vellend":{"dur":66.467,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":16.244,"cap":"Mark Vellend’s theory of ecological communities, developed in 2010 and 2016, reduces community ecology to four high-level processes, borrowed from population genetics: selection, drift, dispersal, and speciation."}],"end":16.244},{"start":16.994,"sents":[{"start":16.994,"end":27.236,"cap":"Selection means deterministic fitness differences among species: niches, competition, predation, and the stabilizing and equalizing mechanisms of coexistence theory."},{"start":27.556,"end":32.82,"cap":"Drift is demographic chance, decisive in small populations and the engine of neutral theory."},{"start":33.14,"end":40.483,"cap":"Dispersal moves organisms among places, from island colonization to metapopulation rescue to metacommunity mass effects."},{"start":40.803,"end":43.65,"cap":"Speciation adds new species to the regional pool."}],"end":43.65},{"start":44.4,"sents":[{"start":44.4,"end":47.113,"cap":"Every chapter you have seen is a particular blend."},{"start":47.433,"end":51.435,"cap":"Island biogeography is dispersal set against stochastic extinction."},{"start":51.755,"end":55.323,"cap":"Metapopulations are colonization and extinction among patches."},{"start":55.643,"end":58.176,"cap":"Species sorting is selection plus dispersal."},{"start":58.496,"end":63.667,"cap":"Neutral theory is drift, dispersal, and speciation, with selection set to zero."}],"end":63.667}],"sig":"949:0,0,1.5"},"syn-review":{"dur":54.393,"beats":[{"start":1.1,"sents":[{"start":1.1,"end":4.262,"cap":"Before your exam, rehearse with questions like these."},{"start":4.582,"end":7.649,"cap":"Why is a Type II functional response destabilizing?"},{"start":7.969,"end":10.526,"cap":"Why does the species with the lowest R* win?"},{"start":10.846,"end":13.855,"cap":"Why don’t empty patches mean habitat is unimportant?"}],"end":13.855},{"start":16.105,"sents":[{"start":16.105,"end":19.718,"cap":"What separates a stabilizing mechanism from an equalizing one?"},{"start":20.038,"end":25.213,"cap":"How do the four metacommunity paradigms differ in dispersal and environmental heterogeneity?"},{"start":25.533,"end":28.49,"cap":"And what does the fundamental biodiversity number measure?"}],"end":28.49},{"start":30.74,"sents":[{"start":30.74,"end":42.73,"cap":"If you can sketch the graphs from memory, the isoclines, the immigration and extinction curves, the phase planes, and explain what moves each line, you understand the theory, not just its vocabulary."},{"start":43.05,"end":46.508,"cap":"The ecological theater is vast, but its rules are learnable."},{"start":46.828,"end":47.393,"cap":"Good luck."}],"end":47.393}],"sig":"695:1.5,1.5,3"}};
